-- ===========================================================================
-- BizPilot — 0001 core schema
-- Multi-tenant business management & accounts receivable.
--
-- CONVENTIONS
--   * Every tenant-owned table carries `business_id uuid not null`.
--   * Money is stored as NUMERIC(20,0) whole paise. Never float, never numeric
--     without a scale.
--   * Business dates are `date` (no time zone). Timestamps are `timestamptz`.
--   * Primary keys are UUIDs generated by the database.
--   * Document lifecycle (draft/issued/void) is stored; payment and overdue
--     status are DERIVED from allocations + due dates, never stored.
-- ===========================================================================

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- Enumerated types
-- ---------------------------------------------------------------------------
create type public.member_role as enum (
  'owner',
  'admin',
  'accountant',
  'collection_staff',
  'read_only'
);

create type public.invitation_status as enum ('pending', 'accepted', 'revoked');

create type public.document_state as enum ('draft', 'issued', 'void');

create type public.payment_method as enum ('cash', 'bank_transfer', 'upi', 'cheque', 'card', 'other');

create type public.cheque_status as enum ('not_applicable', 'pending', 'cleared', 'bounced');

create type public.audit_action as enum (
  'business.created',
  'business.updated',
  'member.invited',
  'member.role_changed',
  'member.removed',
  'customer.created',
  'customer.updated',
  'customer.deleted',
  'invoice.created',
  'invoice.updated',
  'invoice.issued',
  'invoice.voided',
  'payment.recorded',
  'payment.allocated',
  'payment.reversed',
  'reminder.logged',
  'settings.updated'
);

-- ---------------------------------------------------------------------------
-- Shared trigger: maintain updated_at
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- businesses
-- ---------------------------------------------------------------------------
create table public.businesses (
  id uuid primary key default gen_random_uuid(),
  legal_name text not null check (length(trim(legal_name)) between 1 and 200),
  display_name text not null check (length(trim(display_name)) between 1 and 120),
  business_type text,
  gstin text check (gstin is null or gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$'),
  address_line1 text,
  address_line2 text,
  city text,
  state_code text check (state_code is null or state_code ~ '^[0-9]{2}$'),
  postal_code text,
  phone text,
  email text,
  currency text not null default 'INR' check (currency = 'INR'),
  timezone text not null default 'Asia/Kolkata',
  financial_year_start_month smallint not null default 4 check (financial_year_start_month between 1 and 12),
  invoice_prefix text not null default 'INV' check (length(invoice_prefix) between 1 and 10),
  default_credit_period_days smallint not null default 30 check (default_credit_period_days between 0 and 365),
  default_tax_rate_basis_points integer not null default 1800 check (default_tax_rate_basis_points between 0 and 10000),
  is_gst_registered boolean not null default false,
  reminder_template text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger businesses_set_updated_at
  before update on public.businesses
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- profiles (1:1 with auth.users)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  phone text,
  avatar_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- business_members
-- ---------------------------------------------------------------------------
create table public.business_members (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  role public.member_role not null default 'read_only',
  invitation_status public.invitation_status not null default 'accepted',
  invited_email text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (business_id, user_id)
);

create index business_members_user_idx on public.business_members (user_id);
create index business_members_business_idx on public.business_members (business_id);

create trigger business_members_set_updated_at
  before update on public.business_members
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- customers
-- ---------------------------------------------------------------------------
create table public.customers (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  customer_name text not null check (length(trim(customer_name)) between 1 and 200),
  phone text,
  email text,
  gstin text check (gstin is null or gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$'),
  billing_address text,
  shipping_address text,
  city text,
  state_code text check (state_code is null or state_code ~ '^[0-9]{2}$'),
  credit_period_days smallint not null default 30 check (credit_period_days between 0 and 365),
  credit_limit_paise numeric(20,0) not null default 0 check (credit_limit_paise >= 0),
  notes text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- A phone number identifies a customer within a business (issue #4: duplicates).
create unique index customers_business_phone_key
  on public.customers (business_id, phone)
  where phone is not null;

create index customers_business_name_idx on public.customers (business_id, lower(customer_name));

create trigger customers_set_updated_at
  before update on public.customers
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- invoice_sequences — atomic per business / financial year numbering
-- ---------------------------------------------------------------------------
create table public.invoice_sequences (
  business_id uuid not null references public.businesses (id) on delete cascade,
  financial_year text not null check (financial_year ~ '^\d{4}-\d{2}$'),
  prefix text not null default 'INV',
  last_number integer not null default 0 check (last_number >= 0),
  updated_at timestamptz not null default now(),
  primary key (business_id, financial_year)
);

-- ---------------------------------------------------------------------------
-- invoices
-- ---------------------------------------------------------------------------
create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  customer_id uuid not null references public.customers (id) on delete restrict,
  invoice_number text not null check (length(trim(invoice_number)) between 1 and 40),
  financial_year text not null check (financial_year ~ '^\d{4}-\d{2}$'),
  invoice_date date not null,
  due_date date not null,
  document_state public.document_state not null default 'draft',
  place_of_supply_state_code text check (place_of_supply_state_code is null or place_of_supply_state_code ~ '^[0-9]{2}$'),
  gst_mode text not null default 'intra_state' check (gst_mode in ('intra_state', 'inter_state', 'exempt')),
  subtotal_paise numeric(20,0) not null default 0 check (subtotal_paise >= 0),
  discount_paise numeric(20,0) not null default 0 check (discount_paise >= 0),
  taxable_amount_paise numeric(20,0) not null default 0 check (taxable_amount_paise >= 0),
  cgst_paise numeric(20,0) not null default 0 check (cgst_paise >= 0),
  sgst_paise numeric(20,0) not null default 0 check (sgst_paise >= 0),
  igst_paise numeric(20,0) not null default 0 check (igst_paise >= 0),
  cess_paise numeric(20,0) not null default 0 check (cess_paise >= 0),
  total_tax_paise numeric(20,0) not null default 0 check (total_tax_paise >= 0),
  total_amount_paise numeric(20,0) not null default 0 check (total_amount_paise >= 0),
  -- Immutable snapshot of the customer at issue time (issue #3: history must
  -- not change when the customer profile is edited later).
  customer_snapshot jsonb,
  notes text,
  issued_at timestamptz,
  voided_at timestamptz,
  void_reason text,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint invoices_due_after_invoice check (due_date >= invoice_date),
  constraint invoices_issued_requires_timestamp check (
    (document_state = 'draft' and issued_at is null)
    or (document_state in ('issued', 'void') and issued_at is not null)
  ),
  constraint invoices_void_requires_reason check (
    document_state <> 'void' or (voided_at is not null and void_reason is not null)
  )
);

-- Duplicate issued invoice numbers are impossible (issue #5).
create unique index invoices_business_number_key
  on public.invoices (business_id, invoice_number)
  where document_state <> 'draft';

create index invoices_business_due_idx on public.invoices (business_id, due_date);
create index invoices_business_customer_idx on public.invoices (business_id, customer_id);
create index invoices_business_state_idx on public.invoices (business_id, document_state);
create index invoices_business_date_idx on public.invoices (business_id, invoice_date desc);

create trigger invoices_set_updated_at
  before update on public.invoices
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- invoice_items
-- ---------------------------------------------------------------------------
create table public.invoice_items (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  invoice_id uuid not null references public.invoices (id) on delete cascade,
  line_number integer not null check (line_number > 0),
  description text not null check (length(trim(description)) between 1 and 500),
  hsn_sac text,
  quantity numeric(14,3) not null check (quantity > 0),
  unit text,
  unit_price_paise numeric(20,0) not null check (unit_price_paise >= 0),
  discount_percent_basis_points integer not null default 0 check (discount_percent_basis_points between 0 and 10000),
  gross_amount_paise numeric(20,0) not null check (gross_amount_paise >= 0),
  discount_paise numeric(20,0) not null default 0 check (discount_paise >= 0),
  taxable_amount_paise numeric(20,0) not null check (taxable_amount_paise >= 0),
  tax_rate_basis_points integer not null default 0 check (tax_rate_basis_points between 0 and 10000),
  cgst_paise numeric(20,0) not null default 0 check (cgst_paise >= 0),
  sgst_paise numeric(20,0) not null default 0 check (sgst_paise >= 0),
  igst_paise numeric(20,0) not null default 0 check (igst_paise >= 0),
  cess_paise numeric(20,0) not null default 0 check (cess_paise >= 0),
  line_total_paise numeric(20,0) not null check (line_total_paise >= 0),
  created_at timestamptz not null default now(),
  unique (invoice_id, line_number)
);

create index invoice_items_invoice_idx on public.invoice_items (invoice_id);
create index invoice_items_business_idx on public.invoice_items (business_id);

-- ---------------------------------------------------------------------------
-- payments
-- ---------------------------------------------------------------------------
create table public.payments (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  customer_id uuid not null references public.customers (id) on delete restrict,
  payment_date date not null,
  amount_paise numeric(20,0) not null check (amount_paise > 0),
  payment_method public.payment_method not null default 'cash',
  reference_number text,
  cheque_status public.cheque_status not null default 'not_applicable',
  notes text,
  idempotency_key text not null check (length(idempotency_key) between 8 and 100),
  -- Reversal is a correction record, never a delete (issue #11).
  reversed_at timestamptz,
  reversed_by uuid references auth.users (id) on delete set null,
  reversal_reason text,
  reverses_payment_id uuid references public.payments (id) on delete restrict,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payments_reversal_consistency check (
    (reversed_at is null and reversed_by is null and reversal_reason is null)
    or (reversed_at is not null and reversal_reason is not null)
  ),
  constraint payments_cheque_status check (
    payment_method = 'cheque' or cheque_status = 'not_applicable'
  )
);

-- Idempotency: a repeated submit can never create a second payment (issue #2).
create unique index payments_business_idempotency_key
  on public.payments (business_id, idempotency_key);

create index payments_business_date_idx on public.payments (business_id, payment_date desc);
create index payments_business_customer_idx on public.payments (business_id, customer_id);

create trigger payments_set_updated_at
  before update on public.payments
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- payment_allocations — the heart of accurate receivables
-- ---------------------------------------------------------------------------
create table public.payment_allocations (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  payment_id uuid not null references public.payments (id) on delete cascade,
  invoice_id uuid not null references public.invoices (id) on delete restrict,
  allocated_amount_paise numeric(20,0) not null check (allocated_amount_paise > 0),
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  unique (payment_id, invoice_id)
);

create index payment_allocations_invoice_idx on public.payment_allocations (invoice_id);
create index payment_allocations_payment_idx on public.payment_allocations (payment_id);
create index payment_allocations_business_idx on public.payment_allocations (business_id);

-- ---------------------------------------------------------------------------
-- reminder_logs — proof of follow-up, recorded only on explicit confirmation
-- ---------------------------------------------------------------------------
create table public.reminder_logs (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  customer_id uuid not null references public.customers (id) on delete cascade,
  invoice_id uuid references public.invoices (id) on delete set null,
  channel text not null default 'whatsapp' check (channel in ('whatsapp', 'phone', 'email', 'other')),
  message text,
  sent_at timestamptz not null default now(),
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index reminder_logs_business_idx on public.reminder_logs (business_id, sent_at desc);
create index reminder_logs_invoice_idx on public.reminder_logs (invoice_id);

-- ---------------------------------------------------------------------------
-- audit_logs — append-only financial history
-- ---------------------------------------------------------------------------
create table public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,
  entity_type text not null,
  entity_id uuid,
  action public.audit_action not null,
  previous_values jsonb,
  new_values jsonb,
  created_at timestamptz not null default now()
);

create index audit_logs_business_created_idx on public.audit_logs (business_id, created_at desc);
create index audit_logs_entity_idx on public.audit_logs (entity_type, entity_id);
